-- Trigger para atualizar updated_at automaticamente
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS update_entregas_updated_at ON public.entregas;
CREATE TRIGGER update_entregas_updated_at
BEFORE UPDATE ON public.entregas
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- Trigger para validar valores positivos em frete
CREATE OR REPLACE FUNCTION public.validate_frete_values()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.valor_frete < 0 THEN
        RAISE EXCEPTION 'O valor do frete não pode ser negativo.';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS validate_entregas_frete ON public.entregas;
CREATE TRIGGER validate_entregas_frete
BEFORE INSERT OR UPDATE ON public.entregas
FOR EACH ROW EXECUTE FUNCTION public.validate_frete_values();

-- Adicionar coluna deleted_at
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.coletas ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.clientes ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.fornecedores ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;
ALTER TABLE public.transportadoras ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMP WITH TIME ZONE;

-- Criar índices para performance nas queries filtradas
CREATE INDEX IF NOT EXISTS idx_entregas_deleted_at ON public.entregas(deleted_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_coletas_deleted_at ON public.coletas(deleted_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_clientes_deleted_at ON public.clientes(deleted_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_fornecedores_deleted_at ON public.fornecedores(deleted_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_transportadoras_deleted_at ON public.transportadoras(deleted_at) WHERE deleted_at IS NULL;

-- Atualizar RLS para esconder deletados por padrão (exemplo para entregas)
-- Nota: As policies existentes precisam ser ajustadas se quiserem ocultar automaticamente.
-- Por enquanto, a filtragem será feita no nível de aplicação (hooks) para evitar quebras em massa.

-- Create the telemetry_logs table
CREATE TABLE IF NOT EXISTS public.telemetry_logs (
    id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    severity TEXT NOT NULL CHECK (severity IN ('info', 'warning', 'error', 'critical')),
    category TEXT NOT NULL,
    message TEXT NOT NULL,
    stack_trace TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    user_id UUID REFERENCES auth.users(id),
    device_info JSONB DEFAULT '{}'::jsonb,
    url TEXT
);

-- Enable RLS
ALTER TABLE public.telemetry_logs ENABLE ROW LEVEL SECURITY;

-- Create policies
CREATE POLICY "Anyone can insert telemetry logs" 
ON public.telemetry_logs 
FOR INSERT 
WITH CHECK (true);

CREATE POLICY "Admins can view all telemetry logs" 
ON public.telemetry_logs 
FOR SELECT 
USING (
    EXISTS (
        SELECT 1 FROM public.user_roles
        WHERE user_roles.user_id = auth.uid()
        AND user_roles.role = 'admin'
    )
);

-- Create a function to delete old telemetry logs
CREATE OR REPLACE FUNCTION public.cleanup_old_telemetry_logs()
RETURNS void AS $$
BEGIN
    DELETE FROM public.telemetry_logs
    WHERE created_at < now() - INTERVAL '30 days';
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create an index for faster lookups
CREATE INDEX IF NOT EXISTS idx_telemetry_logs_category ON public.telemetry_logs(category);
CREATE INDEX IF NOT EXISTS idx_telemetry_logs_severity ON public.telemetry_logs(severity);
CREATE INDEX IF NOT EXISTS idx_telemetry_logs_created_at ON public.telemetry_logs(created_at DESC);

-- 1. Optimistic Locking
-- Add version column to critical tables
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;
ALTER TABLE public.cotacoes_frete ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;
ALTER TABLE public.transportadoras ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 1;

-- Function to increment version
CREATE OR REPLACE FUNCTION public.increment_version()
RETURNS TRIGGER AS $$
BEGIN
  NEW.version = OLD.version + 1;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Create triggers
DROP TRIGGER IF EXISTS tr_entregas_version ON public.entregas;
CREATE TRIGGER tr_entregas_version
BEFORE UPDATE ON public.entregas
FOR EACH ROW
EXECUTE FUNCTION public.increment_version();

DROP TRIGGER IF EXISTS tr_cotacoes_frete_version ON public.cotacoes_frete;
CREATE TRIGGER tr_cotacoes_frete_version
BEFORE UPDATE ON public.cotacoes_frete
FOR EACH ROW
EXECUTE FUNCTION public.increment_version();

DROP TRIGGER IF EXISTS tr_transportadoras_version ON public.transportadoras;
CREATE TRIGGER tr_transportadoras_version
BEFORE UPDATE ON public.transportadoras
FOR EACH ROW
EXECUTE FUNCTION public.increment_version();

-- 2. Partitioning audit_logs
-- Since we can't easily convert an existing table to partitioned without data migration,
-- we'll create a new partitioned table and migrate if possible, or start new.
-- Given the 'Lovable' context, we'll try to be safe.

-- Rename current table to backup
ALTER TABLE public.audit_logs RENAME TO audit_logs_old;

-- Create partitioned table
CREATE TABLE public.audit_logs (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    user_id UUID,
    action TEXT NOT NULL,
    entity_type TEXT NOT NULL,
    entity_id TEXT NOT NULL,
    old_data JSONB,
    new_data JSONB,
    ip_address TEXT,
    user_agent TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
) PARTITION BY RANGE (created_at);

-- Add primary key (must include partition key)
ALTER TABLE public.audit_logs ADD PRIMARY KEY (id, created_at);

-- Create initial partitions
CREATE TABLE public.audit_logs_y2026m01 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');
CREATE TABLE public.audit_logs_y2026m02 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');
CREATE TABLE public.audit_logs_y2026m03 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-03-01') TO ('2026-04-01');
CREATE TABLE public.audit_logs_y2026m04 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-04-01') TO ('2026-05-01');
CREATE TABLE public.audit_logs_y2026m05 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-05-01') TO ('2026-06-01');
CREATE TABLE public.audit_logs_y2026m06 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE public.audit_logs_y2026m07 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE public.audit_logs_y2026m08 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');
CREATE TABLE public.audit_logs_y2026m09 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE public.audit_logs_y2026m10 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');
CREATE TABLE public.audit_logs_y2026m11 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
CREATE TABLE public.audit_logs_y2026m12 PARTITION OF public.audit_logs FOR VALUES FROM ('2026-12-01') TO ('2027-01-01');

-- Re-enable RLS on new table
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

-- Migration of data (optional but recommended)
-- INSERT INTO public.audit_logs SELECT * FROM public.audit_logs_old;

-- Note: We need to recreate policies for the new table
CREATE POLICY "Admin can view all audit logs" ON public.audit_logs FOR SELECT USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'));

-- 1. Drop the incorrect partitioned table and its partitions
DROP TABLE IF EXISTS public.audit_logs CASCADE;

-- 2. Re-create partitioned table with correct columns
CREATE TABLE public.audit_logs (
    id UUID NOT NULL DEFAULT gen_random_uuid(),
    table_name TEXT NOT NULL,
    record_id TEXT NOT NULL,
    action TEXT NOT NULL,
    old_data JSONB,
    new_data JSONB,
    changed_fields TEXT[],
    user_id UUID,
    user_email TEXT,
    user_name TEXT,
    ip_address TEXT,
    user_agent TEXT,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
) PARTITION BY RANGE (created_at);

-- Add primary key (must include partition key)
ALTER TABLE public.audit_logs ADD PRIMARY KEY (id, created_at);

-- 3. Re-create initial partitions and enable RLS on each
DO $$
DECLARE
    m INTEGER;
    partition_name TEXT;
    start_date TEXT;
    end_date TEXT;
BEGIN
    FOR m IN 1..12 LOOP
        partition_name := 'audit_logs_y2026m' || LPAD(m::text, 2, '0');
        start_date := '2026-' || LPAD(m::text, 2, '0') || '-01';
        -- Simple logic for end date (next month)
        IF m = 12 THEN
            end_date := '2027-01-01';
        ELSE
            end_date := '2026-' || LPAD((m+1)::text, 2, '0') || '-01';
        END IF;

        EXECUTE format('CREATE TABLE public.%I PARTITION OF public.audit_logs FOR VALUES FROM (%L) TO (%L)', partition_name, start_date, end_date);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', partition_name);
    END LOOP;
END $$;

-- 4. Enable RLS on parent table
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;

-- 5. Re-create policies
CREATE POLICY "Admin can view all audit logs" ON public.audit_logs FOR SELECT USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'));
CREATE POLICY "Users can view their own audit logs" ON public.audit_logs FOR SELECT USING (user_id = auth.uid());
CREATE POLICY "System can insert audit logs" ON public.audit_logs FOR INSERT WITH CHECK (true);

-- 6. Migrate data from backup (if it exists)
INSERT INTO public.audit_logs (id, table_name, record_id, action, old_data, new_data, changed_fields, user_id, user_email, user_name, ip_address, user_agent, created_at)
SELECT id, table_name, record_id, action, old_data, new_data, changed_fields, user_id, user_email, user_name, ip_address, user_agent, created_at FROM public.audit_logs_old;

-- 7. Drop backup table
DROP TABLE public.audit_logs_old;

-- 1. Idempotency table for external webhooks
CREATE TABLE IF NOT EXISTS public.webhook_events_processed (
    id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    external_event_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    processed_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
    metadata JSONB,
    CONSTRAINT unique_external_event_per_provider UNIQUE (external_event_id, provider)
);

-- Enable RLS
ALTER TABLE public.webhook_events_processed ENABLE ROW LEVEL SECURITY;

-- Policies for idempotency table
CREATE POLICY "System can manage webhook events" ON public.webhook_events_processed FOR ALL USING (true) WITH CHECK (true);

-- 2. Audit Logs Policies (Ensuring they are applied to partitions)
DO $$
DECLARE
    partition_name TEXT;
    m INTEGER;
BEGIN
    FOR m IN 1..12 LOOP
        partition_name := 'audit_logs_y2026m' || LPAD(m::text, 2, '0');

        -- Select Policy
        EXECUTE format('DROP POLICY IF EXISTS "Admin can view all audit logs" ON public.%I', partition_name);
        EXECUTE format('CREATE POLICY "Admin can view all audit logs" ON public.%I FOR SELECT USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', partition_name);

        EXECUTE format('DROP POLICY IF EXISTS "Users can view their own audit logs" ON public.%I', partition_name);
        EXECUTE format('CREATE POLICY "Users can view their own audit logs" ON public.%I FOR SELECT USING (user_id = auth.uid())', partition_name);

        -- Insert Policy
        EXECUTE format('DROP POLICY IF EXISTS "System can insert audit logs" ON public.%I', partition_name);
        EXECUTE format('CREATE POLICY "System can insert audit logs" ON public.%I FOR INSERT WITH CHECK (true)', partition_name);
    END LOOP;
END $$;

-- Optimistic Locking Columns
DO $$ 
BEGIN 
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'entregas' AND column_name = 'version') THEN
        ALTER TABLE public.entregas ADD COLUMN version INTEGER DEFAULT 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'cotacoes_frete' AND column_name = 'version') THEN
        ALTER TABLE public.cotacoes_frete ADD COLUMN version INTEGER DEFAULT 1;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'transportadoras' AND column_name = 'version') THEN
        ALTER TABLE public.transportadoras ADD COLUMN version INTEGER DEFAULT 1;
    END IF;
END $$;

-- Triggers for Version Increment
CREATE OR REPLACE FUNCTION increment_version()
RETURNS TRIGGER AS $$
BEGIN
  NEW.version = OLD.version + 1;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS tr_increment_version_entregas ON public.entregas;
CREATE TRIGGER tr_increment_version_entregas
BEFORE UPDATE ON public.entregas
FOR EACH ROW
WHEN (OLD.* IS DISTINCT FROM NEW.*)
EXECUTE FUNCTION increment_version();

DROP TRIGGER IF EXISTS tr_increment_version_cotacoes_frete ON public.cotacoes_frete;
CREATE TRIGGER tr_increment_version_cotacoes_frete
BEFORE UPDATE ON public.cotacoes_frete
FOR EACH ROW
WHEN (OLD.* IS DISTINCT FROM NEW.*)
EXECUTE FUNCTION increment_version();

-- Performance Indexes
CREATE INDEX IF NOT EXISTS idx_entregas_status ON public.entregas(status);
CREATE INDEX IF NOT EXISTS idx_webhook_events_lookup ON public.webhook_events_processed(provider, external_event_id);

-- Optimistic Locking Infrastructure
ALTER TABLE public.entregas ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 0;
ALTER TABLE public.coletas ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 0;
ALTER TABLE public.transportadoras ADD COLUMN IF NOT EXISTS version INTEGER DEFAULT 0;

-- Function to increment version
CREATE OR REPLACE FUNCTION public.increment_version_column()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.version = COALESCE(OLD.version, 0) + 1;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply triggers
DROP TRIGGER IF EXISTS tr_version_entregas ON public.entregas;
CREATE TRIGGER tr_version_entregas
BEFORE UPDATE ON public.entregas
FOR EACH ROW
EXECUTE FUNCTION public.increment_version_column();

DROP TRIGGER IF EXISTS tr_version_coletas ON public.coletas;
CREATE TRIGGER tr_version_coletas
BEFORE UPDATE ON public.coletas
FOR EACH ROW
EXECUTE FUNCTION public.increment_version_column();

DROP TRIGGER IF EXISTS tr_version_transportadoras ON public.transportadoras;
CREATE TRIGGER tr_version_transportadoras
BEFORE UPDATE ON public.transportadoras
FOR EACH ROW
EXECUTE FUNCTION public.increment_version_column();

-- Webhook Idempotency Infrastructure
