-- 4. Audit Trail for non-partitioned tables
DO $$
DECLARE
    t text;
BEGIN
    FOR t IN 
        SELECT relname 
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'public' 
        AND c.relkind = 'r' -- regular table
        AND NOT c.relispartition -- not a partition
        AND relname NOT LIKE 'audit_logs%'
        AND relname NOT IN ('schema_migrations', 'architecture_decisions')
    LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS audit_log_trigger ON public.%I', t);
        EXECUTE format('CREATE TRIGGER audit_log_trigger AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION audit_log_trigger()', t);
    END LOOP;
END;
$$;

-- 1. Fix search_path for user-defined functions only
DO $$
DECLARE
    f record;
BEGIN
    FOR f IN 
        SELECT p.proname, oidvectortypes(p.proargtypes) as args
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        LEFT JOIN pg_depend d ON d.objid = p.oid AND d.deptype = 'e'
        WHERE n.nspname = 'public'
        AND d.objid IS NULL -- Skip functions owned by extensions
    LOOP
        BEGIN
            EXECUTE format('ALTER FUNCTION public.%I(%s) SET search_path = public', f.proname, f.args);
        EXCEPTION WHEN OTHERS THEN
            RAISE NOTICE 'Could not alter function %', f.proname;
        END;
    END LOOP;
END;
$$;

