CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  BEGIN
    INSERT INTO public.profiles (id, email, full_name)
    VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'full_name',''))
    ON CONFLICT (id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user: profile insert failed for %: %', NEW.id, SQLERRM;
  END;
  BEGIN
    INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'user')
    ON CONFLICT (user_id, role) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'handle_new_user: role insert failed for %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.notify_entrega_concluida()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status = 'entregue' AND (OLD.status IS NULL OR OLD.status <> 'entregue') THEN
    INSERT INTO notifications (user_id, title, message, type, action_url, metadata)
    SELECT DISTINCT ur.user_id, 'Entrega Concluída! 🎉',
      'A entrega ' || NEW.numero_entrega || ' foi concluída com sucesso.',
      'success','/envios',
      jsonb_build_object('entrega_id',NEW.id,'numero_entrega',NEW.numero_entrega,'event','entrega_concluida')
    FROM user_roles ur;
  END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.notify_coleta_atrasada()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status IN ('solicitada','em_transito')
     AND NEW.data_prevista_coleta IS NOT NULL
     AND NEW.data_prevista_coleta < NOW()
     AND NEW.data_efetiva_coleta IS NULL THEN
    INSERT INTO notifications (user_id, title, message, type, action_url, metadata)
    SELECT DISTINCT ur.user_id,'Coleta Atrasada ⚠️',
      'A coleta ' || NEW.numero_coleta || ' está atrasada. Previsão era ' || TO_CHAR(NEW.data_prevista_coleta,'DD/MM/YYYY'),
      'warning','/coletas',
      jsonb_build_object('coleta_id',NEW.id,'numero_coleta',NEW.numero_coleta,'event','coleta_atrasada')
    FROM user_roles ur;
  END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.notify_ocorrencia_registrada()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_ref_numero text;
BEGIN
  IF NEW.entrega_id IS NOT NULL THEN
    SELECT numero_entrega INTO v_ref_numero FROM entregas WHERE id = NEW.entrega_id;
  ELSIF NEW.coleta_id IS NOT NULL THEN
    SELECT numero_coleta INTO v_ref_numero FROM coletas WHERE id = NEW.coleta_id;
  ELSE v_ref_numero := 'N/A';
  END IF;
  INSERT INTO notifications (user_id, title, message, type, action_url, metadata)
  SELECT DISTINCT ur.user_id,'Nova Ocorrência Registrada 🚨',
    'Uma ocorrência do tipo "' || NEW.tipo_ocorrencia || '" foi registrada para ' || v_ref_numero,
    'error','/ocorrencias',
    jsonb_build_object('ocorrencia_id',NEW.id,'tipo_ocorrencia',NEW.tipo_ocorrencia,
                       'entrega_id',NEW.entrega_id,'coleta_id',NEW.coleta_id,'event','ocorrencia_registrada')
  FROM user_roles ur;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.notify_frete_interno_concluido()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status = 'entregue' AND (OLD.status IS NULL OR OLD.status <> 'entregue') THEN
    INSERT INTO notifications (user_id, title, message, type, action_url, metadata)
    SELECT DISTINCT ur.user_id,'Frete Interno Concluído! ✅',
      'Frete de ' || NEW.origem || ' para ' || NEW.destino || ' foi entregue. +' || NEW.xp_reward || ' XP!',
      'success','/fretes-internos',
      jsonb_build_object('frete_id',NEW.id,'origem',NEW.origem,'destino',NEW.destino,
                         'xp_reward',NEW.xp_reward,'event','frete_interno_concluido')
    FROM user_roles ur;
  END IF;
  RETURN NEW;
END; $$;

CREATE OR REPLACE FUNCTION public.notify_entrega_atrasada()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.status IN ('despachado','em_transito','saiu_entrega')
     AND NEW.previsao_entrega IS NOT NULL
     AND NEW.previsao_entrega < NOW()
     AND NEW.data_entrega_efetiva IS NULL
     AND NOT EXISTS (
       SELECT 1 FROM notifications
        WHERE metadata->>'entrega_id' = NEW.id::text
          AND metadata->>'event' = 'entrega_atrasada'
          AND created_at > NOW() - INTERVAL '24 hours'
     ) THEN
    INSERT INTO notifications (user_id, title, message, type, action_url, metadata)
    SELECT DISTINCT ur.user_id,'Entrega Atrasada ⚠️',
      'A entrega ' || NEW.numero_entrega || ' está atrasada. Previsão era ' || TO_CHAR(NEW.previsao_entrega,'DD/MM/YYYY'),
      'warning','/envios',
      jsonb_build_object('entrega_id',NEW.id,'numero_entrega',NEW.numero_entrega,
                         'previsao_entrega',NEW.previsao_entrega,'event','entrega_atrasada')
    FROM user_roles ur;
  END IF;
  RETURN NEW;
END; $$;

-- P23: system heartbeat every 5 minutes
CREATE OR REPLACE FUNCTION public.record_heartbeat()
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.system_heartbeat (status, message, checked_at)
  VALUES ('healthy', 'auto-heartbeat', now());
  -- Keep only last 30 days
  DELETE FROM public.system_heartbeat WHERE checked_at < now() - INTERVAL '30 days';
END; $$;
REVOKE ALL ON FUNCTION public.record_heartbeat() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_heartbeat() TO service_role;

-- P18: slow query alerter (requires pg_stat_statements)
CREATE OR REPLACE FUNCTION public.alert_slow_queries(threshold_ms int DEFAULT 500)
RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, extensions AS $$
DECLARE inserted int := 0;
BEGIN
  -- Fails gracefully if pg_stat_statements is not installed
  IF NOT EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_stat_statements') THEN
    RETURN 0;
  END IF;
  EXECUTE format($f$
    INSERT INTO public.nexus_tactical_logs (module, level, message)
    SELECT 'SLOW_QUERY', 'crit',
           'Slow query detected: ' || left(query, 200) || ' avg=' || round(mean_exec_time::numeric, 2) || 'ms calls=' || calls
      FROM extensions.pg_stat_statements
     WHERE mean_exec_time > %s
       AND calls > 10
       AND query NOT LIKE '%%pg_stat_statements%%'
     ORDER BY mean_exec_time DESC
     LIMIT 20
  $f$, threshold_ms);
  GET DIAGNOSTICS inserted = ROW_COUNT;
  RETURN inserted;
END; $$;
REVOKE ALL ON FUNCTION public.alert_slow_queries(int) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.alert_slow_queries(int) TO service_role;

DO $$
BEGIN
  PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'nexus_heartbeat';
  PERFORM cron.schedule('nexus_heartbeat','*/5 * * * *', $CRON$ SELECT public.record_heartbeat(); $CRON$);
  PERFORM cron.unschedule(jobid) FROM cron.job WHERE jobname = 'nexus_slow_queries';
  PERFORM cron.schedule('nexus_slow_queries','0 6 * * *', $CRON$ SELECT public.alert_slow_queries(500); $CRON$);
END $$;

-- P12: revoke EXECUTE from anon/authenticated on sensitive SECURITY DEFINER functions
DO $$
DECLARE
  fn text;
  admin_fns text[] := ARRAY[
    'audit_log_trigger()',
    'audit_trigger_func()',
    'fn_audit_trigger()',
    'trigger_bitrix_alert_notification()',
    'update_carrier_ranking()',
    'update_performance_metrics()',
    'update_device_last_seen()',
    'update_user_rank()',
    'update_updated_at_column()',
    'handle_updated_at()',
    'handle_new_user()',
    'handle_new_user_levels()',
    'log_biometric_anomaly()',
    'notify_coleta_atrasada()',
    'notify_entrega_atrasada()',
    'notify_entrega_concluida()',
    'notify_ocorrencia_registrada()',
    'notify_frete_interno_concluido()',
    'notify_conquista_desbloqueada()',
    'generate_coleta_numero()',
    'generate_entrega_numero()',
    'increment_version()',
    'increment_version_column()',
    'handle_optimistic_locking()',
    'tr_increment_version()',
    'validate_frete_values()',
    'validate_payload_schema(text, jsonb)',
    'reconcile_pending_freights()',
    'system_health_check()',
    'record_heartbeat()',
    'alert_slow_queries(integer)',
    'cleanup_old_notifications(integer)',
    'cleanup_old_telemetry_logs(integer)',
    'cleanup_old_telemetry_logs()',
    'drop_old_partitions(text, text, integer)',
    'execute_nexus_protocol(text, text)',
    'add_user_xp(uuid, integer, integer)',
    'update_user_streak(uuid)',
    'purchase_reward(uuid, uuid)'
  ];
BEGIN
  FOREACH fn IN ARRAY admin_fns LOOP
    BEGIN
      EXECUTE format('REVOKE ALL ON FUNCTION public.%s FROM PUBLIC, anon, authenticated', fn);
      EXECUTE format('GRANT EXECUTE ON FUNCTION public.%s TO service_role', fn);
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'Skipping %: %', fn, SQLERRM;
    END;
  END LOOP;
END$$;

