CREATE OR REPLACE FUNCTION public.get_transaction_health()
RETURNS TABLE(
  total_commits bigint,
  total_rollbacks bigint,
  rollback_ratio_pct numeric,
  deadlocks bigint,
  temp_files bigint,
  temp_bytes bigint,
  stats_since timestamptz,
  hours_since_reset numeric,
  rollbacks_per_hour numeric,
  severity text,
  recommendation text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
  v_hours numeric;
  v_rate numeric;
  v_sev text;
  v_reco text;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT
    COALESCE(sum(xact_commit),0),
    COALESCE(sum(xact_rollback),0),
    COALESCE(sum(deadlocks),0),
    COALESCE(sum(temp_files),0),
    COALESCE(sum(temp_bytes),0),
    min(stats_reset)
  INTO
    total_commits, total_rollbacks, deadlocks, temp_files, temp_bytes, stats_since
  FROM pg_stat_database
  WHERE datname = current_database();

  v_hours := GREATEST(EXTRACT(EPOCH FROM (now() - stats_since))/3600.0, 0.01);
  hours_since_reset := round(v_hours::numeric, 2);
  v_rate := total_rollbacks::numeric / v_hours;
  rollbacks_per_hour := round(v_rate, 2);
  rollback_ratio_pct := CASE WHEN (total_commits+total_rollbacks)>0
    THEN round(100.0 * total_rollbacks / (total_commits+total_rollbacks), 3)
    ELSE 0 END;

  IF v_rate > 100 THEN
    v_sev := 'critical';
    v_reco := 'Taxa alta de rollbacks. Investigar policies RLS, triggers e conflitos de aplicação em edge functions.';
  ELSIF v_rate > 20 THEN
    v_sev := 'warning';
    v_reco := 'Rollbacks elevados. Monitorar tendência e revisar mutations recentes.';
  ELSE
    v_sev := 'ok';
    v_reco := 'Taxa de rollbacks dentro do esperado.';
  END IF;

  severity := v_sev;
  recommendation := v_reco;
  RETURN NEXT;
END;
$$;

REVOKE ALL ON FUNCTION public.get_transaction_health() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_transaction_health() TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.get_wal_health()
RETURNS TABLE(
  db_size_bytes bigint,
  wal_size_bytes bigint,
  wal_to_db_ratio numeric,
  checkpoint_timeout_s integer,
  max_wal_size_mb integer,
  severity text,
  recommendation text
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $$
DECLARE
  v_db bigint;
  v_wal bigint;
  v_ratio numeric;
  v_ckpt integer;
  v_maxwal integer;
  v_sev text;
  v_reco text;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  v_db := pg_database_size(current_database());

  -- WAL size (sum of files under pg_wal)
  SELECT COALESCE(sum((pg_stat_file('pg_wal/'||name, true)).size),0)::bigint
  INTO v_wal
  FROM pg_ls_waldir();

  v_ratio := CASE WHEN v_db>0 THEN round(v_wal::numeric / v_db, 2) ELSE 0 END;

  BEGIN v_ckpt := current_setting('checkpoint_timeout')::integer;
  EXCEPTION WHEN OTHERS THEN v_ckpt := NULL; END;

  BEGIN v_maxwal := (regexp_replace(current_setting('max_wal_size'),'[^0-9]','','g'))::integer;
  EXCEPTION WHEN OTHERS THEN v_maxwal := NULL; END;

  IF v_ratio > 10 THEN
    v_sev := 'critical';
    v_reco := 'WAL desproporcional (>10x do banco). Verificar replicação parada, slots inativos ou wal_keep_size excessivo.';
  ELSIF v_ratio > 5 THEN
    v_sev := 'warning';
    v_reco := 'WAL crescendo além do esperado (>5x). Monitorar checkpoint e slots de replicação.';
  ELSE
    v_sev := 'ok';
    v_reco := 'Razão WAL/DB dentro do esperado.';
  END IF;

  db_size_bytes := v_db;
  wal_size_bytes := v_wal;
  wal_to_db_ratio := v_ratio;
  checkpoint_timeout_s := v_ckpt;
  max_wal_size_mb := v_maxwal;
  severity := v_sev;
  recommendation := v_reco;
  RETURN NEXT;
END;
$$;

